// Fake: a real (lightweight) working implementation of the repo contract
class InMemoryUserRepo {
  constructor() { this.rows = new Map(); }
  save(user) { this.rows.set(user.email, { ...user }); }
  findByEmail(email) { return this.rows.get(email) || null; }
}

// Spy: records how it was called, asserts nothing itself
class EmailSpy {
  constructor() { this.sent = []; }
  send(to, subject) { this.sent.push({ to, subject }); }
}

// Use case under test: mock the boundary (email), use the real repo internally
function register(repo, emailer, email) {
  if (repo.findByEmail(email)) throw new Error('exists');
  repo.save({ email, active: true });
  emailer.send(email, 'Welcome');
}

const repo = new InMemoryUserRepo();
const spy = new EmailSpy();
register(repo, spy, 'ada@x.io');

// State assertion via the fake (Detroit-style)
const stored = repo.findByEmail('ada@x.io');
const stateOk = stored !== null && stored.active === true;

// Interaction assertion via the spy at the real boundary (London discipline at the edge)
const spyOk = spy.sent.length === 1 && spy.sent[0].to === 'ada@x.io' && spy.sent[0].subject === 'Welcome';

console.log(stateOk && spyOk ? 'PASS' : 'FAIL');
